SELECT NULL POSUUID, PROD.FINPROD_MARKET_ID PRODID,/*产品代码=科目余额账套id*/ NULL ORG_CODE,/*TODO：机构代码取sys_para是否合理*/ '03' POSITION_TYPE,/*头寸类型：03科目余额，取配置项*/ '999999' CHL_ID ,/*通道代码：无通道默认'999999'*/ BALANCE.SUBJECT_NO ASSET_CODE,/*资产代码：科目号*/ NULL ASSET_TYPE1,/*人行报表资产一级分类根据映射表映射*/ NULL ASSET_TYPE2,/*人行报表资产二级分类根据映射表映射*/ NULL ASSET_TYPE3,/*人行报表资产三级分类根据映射表映射*/ NULL STARTDATE,/*报表开始日*/ NULL ENDDATE,/*报表结束日*/ NULL BOOKDATE,/*报表统计日期*/ BALANCE.B_CCY BCCY,/*本币币种*/ BALANCE.B_AMT BAMT,/*本币金额=科目余额.原币余额*/ BALANCE.O_CCY OCCY,/*原币币种*/ BALANCE.O_AMT OAMT,/*原币金额=科目余额.原币余额*/ NULL INT_AMT,/*利息金额*/ 1 END_DAYS_ONE,/*剩余期限=1*/ /*剩余期限=产品剩余期限,封闭式取产品到期日-统计日期，开放式：每日开放1，定期开放=下一开放开始日-统计日期*/ decode(decode(proddeclare.REP_OPERATE_MODE,'03','02','04','02','01'),'01',prod.mdate - to_date(#{reportEndDate,jdbcType=VARCHAR},'yyyy-MM-dd'),decode(openrule.OPEN_MODE,'02',1,nvl(OPENPLAN.OPEN_DATE_STR,prod.mdate) - to_date(#{reportEndDate,jdbcType=VARCHAR},'yyyy-MM-dd'))) END_DAYS_PROD, 0 END_DAYS_NULL,/*剩余期限=0*/ balance.BAL_FLAG BAL_FLAG /*余额方向*/ FROM BOK_BALANCE BALANCE/*科目余额表*/ LEFT JOIN BOK_BOOKSET BOOKSET /*投资组合关联账套查询相关信息*/ ON BOOKSET.BOOKSET_ID = BALANCE.BOOKSET_ID LEFT JOIN FIN_PRODUCT PROD/*标的类金融产品表*/ ON PROD.FINPROD_MARKET_ID = BALANCE.BOOKSET_ID LEFT JOIN REP_PROD_DECLARE proddeclare /*申报表 */ ON proddeclare.REP_FINPROD_ID = PROD.Finprod_Id LEFT JOIN FIN_PRODUCT_ADD PRODADD /*产品附属信息表*/ ON BALANCE.BOOKSET_ID=PRODADD.PORTFOLIO_ID and prod.finprod_id = PRODADD.Finprod_Id---过滤分档子产品 LEFT JOIN FIN_CASH_INFO cashinfo /* 现金流信息表*/ ON cashinfo.FINPROD_ID = prod.FINPROD_ID and cashinfo.cash_type_2 ='C01' AND CASHINFO.FINPROD_TYPE='01' and cashinfo.branch = '0' LEFT JOIN FIN_OPEN_RULE openrule /* 开放规则表*/ ON openrule.CASH_ID = cashinfo.CASH_ID AND OPENRULE.OPEN_TYPE IN ('01','03')/*防止申赎俩条影响*/ LEFT JOIN ( SELECT DISTINCT OPENSCH.OPEN_DATE_STR OPEN_DATE_STR, OPENSCH.FINPROD_ID FINPROD_ID from ( /*下一开放起始日取值逻辑：OPEN_START>报表结束日期，按照OPEN_START升序排序并且去重，取第一个日期，若取不到，则取产品到期日*/ SELECT RANK() OVER(PARTITION BY OPLAN.FINPROD_ID ORDER BY OPLAN.FINPROD_ID,OPLAN.OPEN_DATE_STR ASC) RANKNUM, OPLAN.OPEN_DATE_STR OPEN_DATE_STR, oplan.FINPROD_ID FINPROD_ID FROM FIN_OPEN_PLAN OPLAN WHERE OPLAN.BRANCH = 0 AND TO_CHAR(OPLAN.OPEN_DATE_STR,'yyyy-MM-dd') > #{reportEndDate,jdbcType=VARCHAR} ) OPENSCH where OPENSCH.ranknum = 1 ) OPENPLAN/*开放计划*/ ON OPENPLAN.FINPROD_ID = PROD.FINPROD_ID WHERE 1 =1 /*科目余额.余额日期=报表结束日期*/ and to_char(balance.BALANCE_DATE,'yyyy-MM-dd') = #{reportEndDate,jdbcType=VARCHAR} /*标的类金融产品.投管分类=理财产品*/ AND PROD.FINPROD_TYPE2 = 'F16' and BOOKSET.ACCT_SUBJECT_TYPE = 'F18'/*取账套表的主体核算类型为F18投资组合*/ and prodadd.PROFIT_FLAG = '03'/*只取非保本理财产品 */ and prod.p_finprod_id is null---过滤分档子产品 /*科目取初始配置的科目*/
