ER BY OPLAN.FINPROD_ID,OPLAN.OPEN_DATE_STR ASC) RANKNUM, OPLAN.OPEN_DATE_STR OPEN_DATE_STR, oplan.FINPROD_ID FINPROD_ID FROM FIN_OPEN_PLAN OPLAN WHERE OPLAN.BRANCH = 0 AND TO_CHAR(OPLAN.OPEN_DATE_STR,'yyyy-MM-dd') > #{reportEndDate,jdbcType=VARCHAR} ) OPENSCH where OPENSCH.ranknum = 1 ) OPENPLAN/*开放计划*/ ON OPENPLAN.FINPROD_ID = PROD.FINPROD_ID WHERE 1 =1 /*科目余额.余额日期=报表结束日期*/ and to_char(balance.BALANCE_DATE,'yyyy-MM-dd') = #{reportEndDate,jdbcType=VARCHAR} /*标的类金融产品.投管分类=理财产品*/ AND PROD.FINPROD_TYPE2 = 'F16' AND BOOKSET.ACCT_SUBJECT_TYPE = 'F16'/*取账套表的主体核算类型为F16净值型产品货币性产品*/ and prodadd.PROFIT_FLAG = '03'/*只取非保本理财产品 */ and prod.p_finprod_id is null---过滤分档子产品 /*科目取初始配置的科目*/
