select FT.TYPE_8 ASSET_TYPE1, FT.TYPE_6 ASSET_TYPE2, FT.TYPE_7 ASSET_TYPE3, /*拆入和正回购是负债 其他是资产 F08拆借 、F07质押式回购、F10买断式回购*/ decode(FT.TYPE_8,'F07',decode(FT.TYPE_7,'03','02','01'), 'F10',decode(FT.TYPE_7,'03','02','01'), 'F08',decode(FT.TYPE_7,'01','02','01'),'01') POSITION_TYPE, VAL.CDATE BOOKDATE,/*报表统计日期*/ VAL.PORTFOLIO_ID PRODID,/*产品代码*/ nvl(nvl(ffp.FINPROD_MARKET_ID,fp.FINPROD_MARKET_ID),VAL.FINPROD_ID) ASSET_CODE,/*资产代码*/ VAL.CHL_ID CHL_ID,/*通道代码*/ VAL.CCY, NVL(VAL.TDY_FLOAT_INGPL,0)+NVL(VAL.DSC_COST_AMT,0) AMT,/*金额*/ nvl(VAL.TDY_INTINCEXP,0) int_amt,/*利息 组合资产估值.当日应计利息+组合资产估值.其他应收款（本金）+组合资产估值.其他应收款（收益）*/ NVL(VAL.DELAY_PAY_AMT,0) DELAY_PAY_AMT,/*清算款*/ nvl(FP.MDATE,ftp.MDATE) MDATE,/*到期日*/ FP.BLN_AREA BLN_AREA,/*境内、境外*/ tpd.COUNTER_ID,/*交易对手id*/ /**mcp.COUNTER_NAME, 交易对手名称**/ nvl(rab.REP_INDUSTRY,racn.REP_INDUSTRY1) INDUSTRY,/*融资人、发行人行业一级类别*/ racn.REP_PROFIT_TYPE /*项目类收售益权*/ from ptl_sec_valution VAL left join FIN_PRODUCT fp on VAL.FINPROD_ID=fp.FINPROD_ID left join FIN_PRODUCT ffp on fp.P_FINPROD_ID=ffp.FINPROD_ID left join FIN_PRODUCT_TYPE ft on nvl(fp.P_FINPROD_ID,VAL.FINPROD_ID)=FT.FINPROD_ID left join FIN_TRADE_PRODUCT ftp on VAL.FINPROD_ID=ftp.FINPROD_ID left join FIN_PRODUCT_ADD fd on VAL.PORTFOLIO_ID=FD.PORTFOLIO_ID left join (select DISTINCT deal.trade_ID,deal.COUNTER_ID from TRD_PRODUCT_DEAL deal left join fin_product info on info.FINPROD_ID=deal.FINPROD_ID left join FIN_PRODUCT_TYPE ft on nvl(info.P_FINPROD_ID,info.FINPROD_ID)=FT.FINPROD_ID where FT.TYPE_8 in ('F07','F08','F10') and ftp.branch = 0 )tpd on VAL.FINPROD_ID=tpd.trade_ID left join rep_asset_bond rab on rab.REP_FINPROD_ID=VAL.FINPROD_ID left join rep_asset_credit_nonstd racn on racn.REP_FINPROD_ID=VAL.FINPROD_ID where VAL.CDATE=#{bookdate,jdbcType=DATE} and exists( select 1 from FIN_PRODUCT_ADD fp3 where fp3.PORTFOLIO_ID = VAL.PORTFOLIO_ID) and FT.TYPE_8 is not null and fd.PROFIT_FLAG = '03'
