SELECT NULL POSUUID, PRODinfo.prod_id PRODID,/*产品代码=科目余额账套id*/ NULL ORG_CODE,/*TODO：机构代码取sys_para是否合理*/ '03' POSITION_TYPE,/*头寸类型：03科目余额，取配置项*/ '999999' CHL_ID ,/*通道代码：无通道默认'999999'*/ BALANCE.SUBJECT_NO ASSET_CODE,/*资产代码：科目号*/ NULL ASSET_TYPE1,/*人行报表资产一级分类根据映射表映射*/ NULL ASSET_TYPE2,/*人行报表资产二级分类根据映射表映射*/ NULL ASSET_TYPE3,/*人行报表资产三级分类根据映射表映射*/ NULL STARTDATE,/*报表开始日*/ NULL ENDDATE,/*报表结束日*/ NULL BOOKDATE,/*报表统计日期*/ BALANCE.B_CCY BCCY,/*本币币种*/ BALANCE.B_AMT BAMT,/*本币金额=科目余额.原币余额*/ BALANCE.O_CCY OCCY,/*原币币种*/ BALANCE.O_AMT OAMT,/*原币金额=科目余额.原币余额*/ NULL INT_AMT,/*利息金额*/ 1 END_DAYS_ONE,/*剩余期限=1*/ /*剩余期限=产品剩余期限,01封闭式取产品到期日-统计日期，02开放式：每日开放1，定期开放=下一开放开始日-统计日期*/ /*判断每日开放：去开放计划表中找开房计划如果没有找到则为每日开放*/ decode(decode(prodinfo.OPERATE_MODE,'01','01','02','01','02'),'01',prodinfo.mdate - to_date(#{reportEndDate,jdbcType=VARCHAR},'yyyy-MM-dd'),decode(nvl(oplan.prod_id,'NOPLAN'),'NOPLAN',1,nvl(OPENPLAN.OPEN_START,prodinfo.mdate) - to_date(#{reportEndDate,jdbcType=VARCHAR},'yyyy-MM-dd'))) END_DAYS_PROD, 0 END_DAYS_NULL,/*剩余期限=0*/ balance.BAL_FLAG BAL_FLAG /*余额方向*/ FROM BOK_BALANCE BALANCE/*科目余额表*/ LEFT JOIN CHB_PRD_BASEINFO PRODINFO /*产品要素信息*/ on prodinfo.PROD_ID = replace(balance.BOOKSET_ID,'F16_') and PRODINFO.status in ('E','M') LEFT JOIN ( SELECT DISTINCT OPENSCH.OPEN_START OPEN_START, OPENSCH.PROD_ID PROD_ID from ( /*下一开放起始日取值逻辑：OPEN_START>报表结束日期，按照OPEN_START升序排序并且去重，取第一个日期，若取不到，则取产品到期日*/ SELECT RANK() OVER(PARTITION BY OPLAN.PROD_ID ORDER BY OPLAN.OPEN_START ASC) RANKNUM, OPLAN.OPEN_START OPEN_START, oplan.PROD_ID PROD_ID FROM chb_prd_opensch OPLAN WHERE 1 =1 AND TO_CHAR(OPLAN.OPEN_START,'yyyy-MM-dd') > #{reportEndDate,jdbcType=VARCHAR} ) OPENSCH where OPENSCH.ranknum = 1 ) OPENPLAN/*开放计划*/ ON OPENPLAN.PROD_ID = PRODINFO.PROD_ID left join ( select prod_id , rank() over (partition by prod_id order by seqno ) ranknum from chb_prd_opensch )oplan ON oplan.PROD_ID = PRODINFO.PROD_ID and ranknum = 1 WHERE 1 =1 /*科目余额.余额日期=报表结束日期*/ and to_char(balance.BALANCE_DATE,'yyyy-MM-dd') = #{reportEndDate,jdbcType=VARCHAR} and prodinfo.PROFIT_TYPE = '03'/*只取非保本理财产品 */ /*科目取初始配置的科目*/
